def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    if n == 1:
        return 'C'
    if n < 10:
        return 'C'
    me = [h[0] for h in history]
    op = [h[1] for h in history]
    my_score = 0
    op_score = 0
    for i in range(n):
        if me[i] == 'C' and op[i] == 'C':
            my_score += 3
            op_score += 3
        elif me[i] == 'C' and op[i] == 'D':
            my_score += 0
            op_score += 5
        elif me[i] == 'D' and op[i] == 'C':
            my_score += 5
            op_score += 0
        else:
            my_score += 1
            op_score += 1
    opp_defects = sum(1 for a in op if a == 'D')
    opp_coops = n - opp_defects
    recent = min(10, n)
    recent_op = op[-recent:]
    recent_defects = sum(1 for a in recent_op if a == 'D')
    if n >= 95:
        if opp_defects * 3 < n:
            return 'D'
        if recent_defects >= recent - 1:
            return 'D'
        return 'C'
    if opp_defects == 0:
        if n >= 90:
            return 'D'
        return 'C'
    if recent_defects == recent:
        if recent_op[-1] == 'D' and recent_op[-2] == 'D':
            return 'D'
        return 'D'
    if recent_defects == 0:
        return 'C'
    defection_rate = opp_defects / n
    if defection_rate > 0.5:
        return 'D'
    if defection_rate > 0.25:
        if n % 3 == 0:
            return 'D'
        return 'C'
    if recent_defects >= 2:
        return 'D'
    return 'C'
